-- ==== BEGIN MIGRATION 20261216000830_pbx_decisions_waiting_count.sql (2585 bytes, sha256 57c3d4292520479f49eb80ffe2eee8edb7fffae4645a98a6afda2118482c57d5) ====
-- A cheap "waiting for your decision" count for the Finance menu entry (completion pass, A8 leftover). ADDITIVE: adds one read-only function; no table, column, policy, trigger
-- or privilege on anything existing changes, and no data changes.
--
-- WHY. The Finance menu entry should show how many project budgets and final-expense sets wait for the person to decide, without making every page load run pbx_inbox(): that
-- function also computes settlement figures and blockers for every open budget of every company the person can read, which is far too much work for a menu badge.
--
-- WHAT. pbx_decisions_waiting_count() returns ONE number: the submitted budget versions plus the submitted final-expense sets that the caller may decide NOW. It uses exactly the
-- predicates pbx_inbox() uses for its two approval lists (company accessible to the caller, pbx_can_decide = the route's capability and not the person who prepared or submitted it,
-- and not on hold because nobody else could decide it), so the number equals the count of rows that pbx_inbox() marks i_can_decide and not on_hold. Not counted: settlement follow-ups
-- (receipts to confirm, ready to close); they stay in the inbox and on My Day. A person who cannot decide anything gets 0, a signed-out caller is refused.
-- The function returns a number only: no project, amount, name or company. Who may decide, every approval function and every other read are unchanged.
-- Rollback: supabase/manual-sql/pbxwait_90_rollback.sql drops the function.

create or replace function pbx_decisions_waiting_count()
returns integer
language plpgsql stable security definer
set search_path = public
as $$
declare
  v_n integer;
begin
  perform pbx_require_user();
  select
    (select count(*) from pbx_budget_versions v
      where v.status = 'submitted' and v.company_id in (select pbx_accessible_company_ids())
        and pbx_can_decide(v.company_id, v.approval_route, v.created_by, v.submitted_by)
        and not pbx_approval_on_hold(v.company_id, v.approval_route, v.created_by, v.submitted_by))
    +
    (select count(*) from pbx_actual_submissions s
      where s.status = 'submitted' and s.company_id in (select pbx_accessible_company_ids())
        and pbx_can_decide(s.company_id, s.approval_route, s.created_by, s.submitted_by)
        and not pbx_approval_on_hold(s.company_id, s.approval_route, s.created_by, s.submitted_by))
    into v_n;
  return v_n;
end;
$$;

revoke all on function pbx_decisions_waiting_count() from public, anon;
grant execute on function pbx_decisions_waiting_count() to authenticated;
-- ==== END MIGRATION 20261216000830_pbx_decisions_waiting_count.sql ====

-- ==== BEGIN MIGRATION 20261216000900_proj_block_task_notifies_pm.sql (4384 bytes, sha256 9b312674b09bf6e7444657c9365fc595ab58da47d856a2f524fe84cdeec416e8) ====
-- A blocker that names someone other than the Project Manager also tells the Project Manager (completion pass, section 2). ADDITIVE: replaces one function in
-- place (create or replace); no table, column, policy or privilege changes, no data changes. Execute privileges are kept by create or replace.
--
-- WHY: proj_block_task told only the named unblocker. When that person was not the PM (a colleague, a team member), the PM, who is accountable for the project,
-- only learned of the blocker by opening the task.
--
-- RULE (unchanged part): the person named as able to unblock the task is told, or the Project Manager when no person is named (only an action is written).
-- NEW: when a person is named and is NOT the Project Manager, the Project Manager is ALSO told ('project_task_blocked' with fyi = true and the unblocker's
-- name, so the notice says who was asked and does not say the PM must act). One notice per person: nothing is sent twice to the same person (the named
-- person is the PM: one notice; proj_notify also deduplicates an unread notice with the same key), and the person who reports the blocker is never told about
-- their own action (proj_notify skips the caller), also when the reporter IS the PM. proj_notify's existing rules still decide who can be reached (an active
-- person who can open the project); nobody gains access to anything.
--
-- UNCHANGED: who may block (assignee, department head, PM), the required reason, the required unblock responsibility (a project member, or a written action), the
-- event record, and proj_unblock_task.

create or replace function proj_block_task(p_task_id uuid, p_reason text, p_unblock_owner uuid default null, p_unblock_action text default null)
returns void
language plpgsql security definer
set search_path = public
as $$
declare
  t proj_tasks;
  v proj_projects;
  v_unblocker text;
begin
  perform proj_require_user();
  select * into t from proj_tasks where id = p_task_id for update;
  if not found then raise exception 'Task not found' using errcode = 'P0002'; end if;
  v := proj_lock_project(t.project_id);
  perform proj_require_open_project(v);
  if proj_task_actor_role(t) is null then raise exception 'Only the assignee, the department head or the Project Manager can block this task' using errcode = '42501'; end if;
  if t.status in ('done', 'cancelled', 'deferred') then raise exception 'A % task cannot be blocked', t.status using errcode = '23514'; end if;
  if length(btrim(coalesce(p_reason, ''))) = 0 then raise exception 'Say what is blocking the task' using errcode = '22023'; end if;
  if p_unblock_owner is null and length(btrim(coalesce(p_unblock_action, ''))) = 0 then
    raise exception 'Say who or what action will unblock it' using errcode = '22023';
  end if;
  if p_unblock_owner is not null and not exists (select 1 from proj_project_members where project_id = v.id and user_id = p_unblock_owner and removed_at is null) then
    raise exception 'The person who can unblock it must be a member of the project' using errcode = '22023';
  end if;
  update proj_tasks set blocked_at = now(), blocked_reason = btrim(p_reason), unblock_owner_id = p_unblock_owner,
         unblock_action = nullif(btrim(p_unblock_action), ''), version = version + 1 where id = t.id;
  perform proj_task_event(t.id, v.id, 'blocked', null, btrim(p_reason), p_unblock_action);
  perform proj_notify(v.id, coalesce(p_unblock_owner, v.pm_user_id), 'project_task_blocked',
    jsonb_build_object('name', v.name, 'reference', v.reference, 'task_id', t.id, 'task', t.title, 'reason', btrim(p_reason)), 'task:' || t.id || ':blocked:' || (t.version + 1));
  -- Also tell the Project Manager when someone else was named (the PM is accountable for the project). Never twice to the same person, never the reporter.
  if p_unblock_owner is not null and v.pm_user_id is not null and v.pm_user_id is distinct from p_unblock_owner then
    select coalesce(nullif(btrim(full_name), ''), split_part(email, '@', 1)) into v_unblocker from profiles where id = p_unblock_owner;
    perform proj_notify(v.id, v.pm_user_id, 'project_task_blocked',
      jsonb_build_object('name', v.name, 'reference', v.reference, 'task_id', t.id, 'task', t.title, 'reason', btrim(p_reason), 'fyi', true, 'unblocker', coalesce(v_unblocker, 'a colleague')),
      'task:' || t.id || ':blocked:' || (t.version + 1));
  end if;
end;
$$;
-- ==== END MIGRATION 20261216000900_proj_block_task_notifies_pm.sql ====

-- ==== BEGIN MIGRATION 20261216000910_module_access_managers.sql (4452 bytes, sha256 c38418dac42c3e6d159e364312a67ef02378df8cb164add2f3b04f0a5c101677) ====
-- Who can grant access to a module, for the people who do not have it (completion pass, B12 / U-13). ADDITIVE: adds one read-only function; no table, column,
-- policy, trigger or privilege on anything existing changes, and no data changes.
--
-- WHY. A person who is denied a module (Sales, Projects, Inventory, Project Budget & Expenses) was told "Ask a founder" with no name. The grant tables are readable
-- only by the people who hold access, so a person without it could not look the names up.
--
-- WHAT. module_access_managers(p_module) returns ONE row per person who can manage that module's access in the CALLER'S OWN COMPANY, and nothing else:
--     user_id (the person's identifier) and display_name.
--   * The company is derived from the caller (their employee record). There is no company argument, so nobody can ask about another company; a caller with no employee
--     record gets no rows.
--   * "Can manage access" is exactly what the module's own grant functions check: Sales, Projects and Inventory: a founder, or a holder of manage_access
--     (the *_has_capability helpers); Project Budget & Expenses: a holder of manage_access (a budget grant has no founder right). Only active, un-revoked grants of that
--     company count, held by an ACTIVE person (an inactive account is never listed, the same join the helpers use).
--   * Module grants are always for one company (company_id is required; they have no country or global form), so unlike role grants there are no country-limited or
--     company-less holders to consider here: a holder of ANOTHER company is never returned.
--   * Not returned: emails, the grant row, capabilities, who granted it, any other company's holders, or any other personnel data.
--   * Callable by any signed-in person, with or without a grant; a signed-out caller is refused; an unknown module is refused.
-- Who may grant, revoke or see grants, and every other function, are unchanged.
-- Rollback: supabase/manual-sql/modaccess_90_rollback.sql drops the function.

create or replace function module_access_managers(p_module text)
returns table (user_id uuid, display_name text)
language plpgsql stable security definer
set search_path = public
as $$
declare
  v_company uuid;
  v_ids uuid[] := '{}';
begin
  if auth.uid() is null then
    raise exception 'Sign in first' using errcode = '42501';
  end if;
  if p_module is null or p_module not in ('sales', 'projects', 'inventory', 'budget') then
    raise exception 'Unknown module' using errcode = '22023';
  end if;
  -- Only the caller's own company, and only for an active caller.
  select e.company_id into v_company
    from employees e join profiles me on me.id = auth.uid() and me.is_active
   where e.user_id = auth.uid() and e.deleted_at is null
   limit 1;
  if v_company is null then return; end if;

  -- One branch per module, so a module that is not installed here cannot break the others.
  if p_module = 'sales' then
    select coalesce(array_agg(distinct g.user_id), '{}') into v_ids from crm_company_grants g
     where g.company_id = v_company and g.revoked_at is null and ('founder' = any (g.capabilities) or 'manage_access' = any (g.capabilities));
  elsif p_module = 'projects' then
    select coalesce(array_agg(distinct g.user_id), '{}') into v_ids from proj_company_grants g
     where g.company_id = v_company and g.revoked_at is null and ('founder' = any (g.capabilities) or 'manage_access' = any (g.capabilities));
  elsif p_module = 'inventory' then
    select coalesce(array_agg(distinct g.user_id), '{}') into v_ids from inv_company_grants g
     where g.company_id = v_company and g.revoked_at is null and ('founder' = any (g.capabilities) or 'manage_access' = any (g.capabilities));
  else
    select coalesce(array_agg(distinct g.user_id), '{}') into v_ids from pbx_company_grants g
     where g.company_id = v_company and g.revoked_at is null and 'manage_access' = any (g.capabilities);
  end if;

  return query
    select h.uid,
           coalesce(nullif(btrim(p.full_name), ''), (select nullif(btrim(e.first_name || ' ' || e.last_name), '') from employees e where e.user_id = h.uid and e.deleted_at is null limit 1), 'A colleague')
      from unnest(v_ids) as h(uid)
      join profiles p on p.id = h.uid and p.is_active
     order by 2, 1;
end;
$$;

revoke all on function module_access_managers(text) from public, anon;
grant execute on function module_access_managers(text) to authenticated;
-- ==== END MIGRATION 20261216000910_module_access_managers.sql ====

-- FINAL ASSERTIONS (key objects exist, the notes switch is OFF). Any failure raises an exception and the whole transaction rolls back.
do $batch_check$
declare
  v_bad text;
  v_on bigint;
begin
  select string_agg('migration ' || c.n || ' (' || c.what || ')', '; ' order by c.n::int) into v_bad
  from (values
    ('3', 'deactivation sets is_active; routing skips inactive people; last CEO/CTO protections', exists (select 1 from pg_proc where pronamespace = 'public'::regnamespace and proname = 'user_is_active')),
    ('4', 'profiles: the deactivation reason is no longer readable directly; System Administrator function added', exists (select 1 from pg_proc where pronamespace = 'public'::regnamespace and proname = 'account_status_details')),
    ('5', 'attendance clock: project-lead candidates function', exists (select 1 from pg_proc where pronamespace = 'public'::regnamespace and proname = 'attendance_lead_candidates')),
    ('6', 'Recovery Leave: decider inbox function', exists (select 1 from pg_proc where pronamespace = 'public'::regnamespace and proname = 'recovery_decider_inbox')),
    ('7', 'policy status function: role check and no anonymous execute', exists (select 1 from pg_proc where pronamespace = 'public'::regnamespace and proname = 'preflight_phase2b_v2_policy_status' and prosrc like '%has_role(''cto'', null, cc.code)%')),
    ('8', 'letters storage: the owning employee reads issued letters only', exists (select 1 from pg_policies where schemaname = 'storage' and tablename = 'objects' and policyname = 'letters_select' and qual like '%generated_letters%')),
    ('9', 'approval routing is country-scoped', exists (select 1 from pg_proc where pronamespace = 'public'::regnamespace and proname = 'resolve_approver' and prosrc like '%ur.country_code is null or ur.country_code = v_country%')),
    ('10', 'scope decision: two narrow read functions', exists (select 1 from pg_proc where pronamespace = 'public'::regnamespace and proname = 'proj_scope_decision_context' and prosrc like '%proj_has_capability%')),
    ('11', 'budget decisions waiting: count function', exists (select 1 from pg_proc where pronamespace = 'public'::regnamespace and proname = 'pbx_decisions_waiting_count' and prosrc like '%pbx_can_decide%')),
    ('12', 'blocker: the Project Manager is told who was asked', exists (select 1 from pg_proc where pronamespace = 'public'::regnamespace and proname = 'proj_block_task' and prosrc like '%Also tell the Project Manager when someone else was named%')),
    ('13', 'ask-for-access names the people who can grant it', exists (select 1 from pg_proc where pronamespace = 'public'::regnamespace and proname = 'module_access_managers' and prosrc like '%One branch per module%'))
  ) c(n, what, present) where not c.present;
  if v_bad is not null then
    raise exception 'Batch install rolled back: not in place after the install: %', v_bad;
  end if;
  select string_agg('migration ' || a.n || ' function ' || a.name, '; ') into v_bad
  from (values ('3', 'user_is_active'), ('3', 'account_deactivation_blockers'), ('3', 'account_holdings'), ('4', 'account_status_details'), ('5', 'attendance_lead_candidates'), ('6', 'recovery_decider_inbox'), ('10', 'proj_scope_decisions_waiting'), ('10', 'proj_scope_decision_context'), ('11', 'pbx_decisions_waiting_count'), ('13', 'module_access_managers')) a(n, name)
  where not exists (select 1 from pg_proc p where p.pronamespace = 'public'::regnamespace and p.proname = a.name);
  if v_bad is not null then
    raise exception 'Batch install rolled back: missing function(s): %', v_bad;
  end if;
  if has_column_privilege('authenticated', 'public.profiles', 'status_reason', 'select') or has_column_privilege('anon', 'public.profiles', 'status_reason', 'select') then
    raise exception 'Batch install rolled back: migration 4 did not restrict SELECT on profiles';
  end if;
  if has_function_privilege('anon', 'public.preflight_phase2b_v2_policy_status()'::regprocedure, 'execute') then
    raise exception 'Batch install rolled back: migration 7 left the policy status function callable by anonymous visitors';
  end if;
end
$batch_check$;

commit;

